// src/services.js — API calls + Socket.IO
import axios from 'axios';
import { io } from 'socket.io-client';

const API = axios.create({ baseURL: '/api' });

export const socket = io('http://localhost:4000', {
  autoConnect: true,
  reconnection: true,
});

// ── Runs ────────────────────────────────────────────────────
export const getRuns        = ()   => API.get('/runs').then(r => r.data);
export const getRunDetail   = (id) => API.get(`/runs/${id}`).then(r => r.data);
export const getSummary     = ()   => API.get('/runs/stats/summary').then(r => r.data);

// ── Tests ───────────────────────────────────────────────────
export const getFailedTests = ()   => API.get('/tests/failed').then(r => r.data);
export const getSlowestTests= ()   => API.get('/tests/slowest').then(r => r.data);

// ── Manual Run ──────────────────────────────────────────────
export const startRun  = (env = {}) => API.post('/manual/run', { env }).then(r => r.data);
export const stopRun   = ()          => API.post('/manual/stop').then(r => r.data);
export const runStatus = ()          => API.get('/manual/status').then(r => r.data);

// ── AI Analysis ─────────────────────────────────────────────
export const analyzeTest = (id) => API.post(`/analysis/analyze/${id}`).then(r => r.data);
